-- Approve at least 4 users per inactive country (KE, TZ, RW, BI, SS, CD, SO)
-- Idempotent: inserts or updates existing kyc_verifications rows to status='approved'

DO $$
BEGIN
-- Kenya: users 10000000...0018 - ...0021
ON CONFLICT (user_id) DO UPDATE SET status='approved', id_verified=TRUE, selfie_verified=TRUE, verified_by=EXCLUDED.verified_by, reviewed_at=EXCLUDED.reviewed_at, expires_at=EXCLUDED.expires_at, updated_at=NOW();

-- Tanzania: users 0035-0038
ON CONFLICT (user_id) DO UPDATE SET status='approved', id_verified=TRUE, selfie_verified=TRUE, verified_by=EXCLUDED.verified_by, reviewed_at=EXCLUDED.reviewed_at, expires_at=EXCLUDED.expires_at, updated_at=NOW();

